    mesh(new T.BoxGeometry(.42, .42, .45), white, 0, .95, .7, g); mesh(new T.BoxGeometry(.3, .18, .1), mat("#f2a7a7"), 0, .85, .95, g);
    for (const sx of [-.15, .15]) { const h = mesh(new T.ConeGeometry(.04, .2, 6), mat("#e8dcc0"), sx, 1.25, .65, g); h.rotation.z = sx * 3; }
    const legs = []; for (const sx of [-.2, .2]) for (const sz of [-.4, .4]) legs.push(mesh(new T.BoxGeometry(.14, .5, .14), white, sx, .25, sz, g));
    cow = { g, legs, follow: false, walk: 0, x: c.x, z: c.z };
