    const [x, z, c] = f, info = D.flowerNames[c], g = new T.Group(); g.position.set(x + .5, 0, z + .5); scene.add(g);
    mesh(new T.CylinderGeometry(.025, .025, .45, 5), mat("#3f8a3a"), 0, .22, 0, g);
